'use strict';
const CONFIG={grade:{title:'Mesa de planejamento',subtitle:'Edição em grade · carteira completa',tag:'01 / GRADE',intro:'Sua carteira, organizada por vendedor e cliente.',desc:'Alterne entre carteiras como nas abas do Excel. Grade e cards usam o mesmo controle.'},agenda:{title:'Central de ações',subtitle:'Consultas, compromissos e próximos passos',tag:'02 / AGENDA',intro:'O próximo passo de cada componente.',desc:'Organize verificações por data e transforme consultas em ações.'},cockpit:{title:'Estação de componentes',subtitle:'Contexto completo · atualização contínua',tag:'03 / COMPONENTE',intro:'Um componente. Todo o contexto.',desc:'Percorra a carteira, consulte as OSs e atualize sem abrir várias janelas.'}};
const C=CONFIG[MODE],KEY='planejador-demo-ficticio-v3-'+MODE,fmtMoney=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const F=[['component','Componente',190],['fleet','Frota/modelo',110],['seller','Vendedor',160],['client','Cliente',230],['site','Site',110],['os','OSs vinculadas',180],['type','Tipo',130],['status','Status do controle',125],['situation','Situação operacional',190],['piecesNote','Observação / peças',290],['note','Observação adicional',290],['nextAction','Próxima ação',280],['owner','Responsável',130],['actionDue','Prazo da ação',120,'date'],['reviewDate','Próxima verificação',135,'date'],['forecast','Previsão conclusão',130,'date'],['confirmed','Última confirmação',135,'date'],['requisition','Requisição',125],['nf','NF',100],['order','Pedido',140],['parts','Peças',130,'money'],['services','Serviços + diversos',150,'money'],['total','Total',140,'calc'],['arrival','Chegada',120,'date'],['notification','Notificação',120,'date'],['opened','Abertura OS',120,'date'],['budgetForecast','Previsão orçamento',140,'date'],['quoted','Entrega orçamento',140,'date'],['decision','Decisão',120],['approved','Aprovação/reprovação',160,'date'],['shipped','Envio',120,'date'],['ltNotification','Chegada → notificação',165,'calc'],['ltBudget','Dias de orçamentação',150,'calc'],['ltApproval','Dias até decisão',140,'calc'],['age','Dias desde notificação',155,'calc'],['internal','Observação interna',260],['invoice','Fatura no mês',115],['invoiceMonth','Mês faturamento',125]];
const FM=Object.fromEntries(F.map(x=>[x[0],x]));
const VIEWS={rotina:['component','fleet','os','seller','client','site','status','situation','piecesNote','note','nextAction','owner','actionDue','reviewDate','forecast','confirmed'],documentos:['component','os','seller','client','type','requisition','nf','order','parts','services','total'],prazos:['component','os','arrival','notification','opened','budgetForecast','quoted','decision','approved','forecast','shipped','ltNotification','ltBudget','ltApproval','age'],completo:F.map(x=>x[0])};
const statuses=['Notificação','Orçamento','Negociação','Aprovado','Pronto','DVO'];
const situations=['A confirmar','Em andamento','Aguardando peças','Aguardando terceiro','Aguardando envio do orçamento','Aguardando negociação/aprovação','Aguardando programação/recurso','Aguardando teste/liberação','Aguardando providência administrativa','Aguardando coleta','Outro'];
let state={schema:'planejador-experimentos',version:1,rows:structuredClone(SEED),referenceDate:'2026-10-23',modifiedAt:'',exportedAt:'',workspaceName:'Carteira fictícia · 48 atendimentos',source:'Base sintética para avaliação · 23/10/2026'};
let sellerFilter=null,clientFilter=null,tabSearch='';
let q='',site='',status='',scope='active',view='rotina',channel='all',visual=MODE==='grade'?'grid':MODE==='agenda'?'board':'dossier',selected=new Set(),active=SEED[0].id,sortKey='',sortDir=1,anchor=null,focusCell=null,rectEnd=null,visibleRows=[],cols=[],undoStack=[],redoStack=[],fileHandle=null,storageOK=true,dirty=false,restored=false,cutRows=null,dragRows=null,modalRow=null,modalTab='rotina',pickPending=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2),today=()=>new Date().toLocaleDateString('en-CA').split('/').reverse().join('-');
function localToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function date(v){return /^\d{4}-\d{2}-\d{2}$/.test(v||'')?v.slice(8)+'/'+v.slice(5,7)+'/'+v.slice(0,4):v||''}
function days(a,b){return a&&b?Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000):''}
function calc(r,k){if(k==='total')return r.parts===''&&r.services===''?'':Number(r.parts||0)+Number(r.services||0);if(k==='ltNotification')return days(r.arrival,r.notification||state.referenceDate);if(k==='ltBudget')return days(r.opened,r.quoted||state.referenceDate);if(k==='ltApproval')return r.quoted?days(r.quoted,r.approved||state.referenceDate):'';if(k==='age')return days(r.notification,state.referenceDate);return r[k]??''}
function display(r,k){let v=calc(r,k),t=FM[k]?.[3];return t==='date'?date(v):['money','calc'].includes(t)&&['parts','services','total'].includes(k)?(v===''?'':fmtMoney.format(v)):v}
function get(id){return state.rows.find(r=>r.id===id)}
function toast(s){$('#toast').textContent=s;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4200)}
function badge(s,kind=''){return `<span class="badge ${kind}">${esc(s||'Sem informação')}</span>`}
function overdue(r){return !!r.actionDue&&r.actionDue<state.referenceDate}
function queue(r){if(overdue(r))return 'late';if(r.reviewDate&&r.reviewDate<=state.referenceDate||r.actionDue===state.referenceDate)return 'today';if(!r.nextAction&&!r.reviewDate&&!r.actionDue)return 'plan';return 'future'}
function filtered(){return state.rows.filter(r=>(scope==='all'||(scope==='archive'?r.archived:!r.archived))&&(!q||F.some(([k])=>String(calc(r,k)).toLocaleLowerCase('pt-BR').includes(q.toLocaleLowerCase('pt-BR'))))&&(!site||r.site===site)&&(!status||r.status===status)&&(channel==='all'||queue(r)===channel)&&(sellerFilter===null||(r.seller||'')===sellerFilter)&&(clientFilter===null||(r.client||'')===clientFilter)).sort((a,b)=>sortKey?sortDir*String(calc(a,sortKey)).localeCompare(String(calc(b,sortKey)),'pt-BR',{numeric:true}):0)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({...state,_dirty:dirty}));storageOK=true}catch{storageOK=false}saveStatus()}
function checkpoint(label){undoStack.push({state:JSON.stringify(state),label});if(undoStack.length>50)undoStack.shift();redoStack=[]}
function history(r,text){r.history=r.history||[];r.history.unshift({at:new Date().toISOString(),text});if(r.history.length>150)r.history.length=150}
function changed(label,ids=[]){dirty=true;state.modifiedAt=new Date().toISOString();ids.forEach(id=>{let r=get(id);if(r)history(r,label)});persist()}
function mutate(label,fn,ids=[]){checkpoint(label);fn();changed(label,ids);render()}
function undo(){if(!undoStack.length)return toast('Nenhuma alteração para desfazer nesta sessão.');let p=undoStack.pop();redoStack.push({state:JSON.stringify(state),label:p.label});state=JSON.parse(p.state);dirty=true;persist();render();toast('Desfeito: '+p.label)}
function redo(){if(!redoStack.length)return;let p=redoStack.pop();undoStack.push({state:JSON.stringify(state),label:p.label});state=JSON.parse(p.state);dirty=true;persist();render();toast('Refeito: '+p.label)}
function saveStatus(){let el=$('#saveState');if(!el)return;el.innerHTML=`<span class="dot ${dirty?'dirty':''}"></span>${storageOK?'Rascunho salvo neste navegador':'Rascunho local indisponível — baixe um backup'}${dirty?' · <b>Há alterações sem backup</b>':' · Sem alterações pendentes de backup'}`;$('#backupTime').textContent=state.exportedAt?'Último backup: '+new Date(state.exportedAt).toLocaleString('pt-BR'):'Backup ainda não baixado';$('#undo')?.toggleAttribute('disabled',!undoStack.length);$('#redo')?.toggleAttribute('disabled',!redoStack.length)}
function shell(){document.body.className=MODE;document.title=C.title+' | Planejador';document.body.innerHTML=`<header class="top"><div class="brand">P</div><div class="heading"><div class="eyebrow">${C.tag}</div><h1>${C.title}</h1><p>${C.subtitle}</p></div><div class="topActions"><button onclick="openFile()">Abrir controle</button><button onclick="examples()">Exemplos</button><button onclick="downloadTable()">Exportar tabela</button><button class="primary" onclick="saveFile()">Salvar backup <small style="color:inherit">Ctrl S</small></button><button class="quiet" onclick="help()">Ajuda / atalhos</button></div></header><div class="savebar"><span id="saveState"></span><span id="backupTime"></span><label>Referência dos prazos <input aria-label="Referência dos prazos" type="date" id="refDate" value="${state.referenceDate}" style="padding:3px 6px" onchange="changeReference(this.value)"></label></div><div id="recovery"></div><div id="body"></div><div id="modal"></div><div id="toast" class="toast" role="status" aria-live="polite"></div><input type="file" id="fileInput" accept=".json" hidden><datalist id="statusOptions">${statuses.map(x=>`<option>${x}</option>`).join('')}</datalist><datalist id="situationOptions">${situations.map(x=>`<option>${x}</option>`).join('')}</datalist>`;$('#fileInput').onchange=loadFile;render();if(restored)$('#recovery').innerHTML=`<div class="recovery"><span><b>Seu rascunho foi retomado.</b> O backup em arquivo continua sendo a cópia para guardar e levar a outro computador.</span><button onclick="this.closest('.recovery').remove()">Entendi</button></div>`}
function stats(){let rows=state.rows.filter(r=>!r.archived);return `<div class="stats"><button class="stat" onclick="setChannel('all')"><small>COMPONENTES / LINHAS</small><strong>${rows.length}</strong><small>Carteira em acompanhamento</small></button><button class="stat" onclick="setChannel('late')"><small>AÇÕES VENCIDAS</small><strong>${rows.filter(overdue).length}</strong><small>Prazo anterior a ${date(state.referenceDate)}</small></button><button class="stat" onclick="setChannel('today')"><small>VERIFICAR AGORA</small><strong>${rows.filter(r=>queue(r)==='today').length}</strong><small>Consultas previstas e ações de hoje</small></button><button class="stat" onclick="setChannel('plan')"><small>SEM AGENDA DEFINIDA</small><strong>${rows.filter(r=>queue(r)==='plan').length}</strong><small>Defina a próxima ação ou verificação</small></button></div>`}
function filters(){let sites=[...new Set(state.rows.map(r=>r.site).filter(Boolean))].sort();return `<div class="filters"><input id="search" placeholder="Buscar componente, OS, vendedor, cliente ou observação…" aria-label="Buscar" value="${esc(q)}"><select aria-label="Filtrar site" onchange="site=this.value;render()"><option value="">Todos os sites</option>${sites.map(x=>`<option ${site===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select aria-label="Filtrar status" onchange="status=this.value;render()"><option value="">Todos os status</option>${[...new Set([...statuses,...state.rows.map(r=>r.status).filter(Boolean)])].map(x=>`<option ${status===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select aria-label="Ativos ou arquivados" onchange="scope=this.value;render()"><option value="active" ${scope==='active'?'selected':''}>Em acompanhamento</option><option value="archive" ${scope==='archive'?'selected':''}>Arquivados</option><option value="all" ${scope==='all'?'selected':''}>Todos</option></select><button onclick="clearFilters()">Limpar filtros</button></div>`}
function tools(){return `<div class="tools"><button class="primary" onclick="addRow()">＋ Linha</button><button onclick="copyRows(false)">Copiar linhas</button><button onclick="copyRows(true)">Recortar linhas</button><button onclick="pasteRowsAfter()">Colar linhas</button><button onclick="duplicateRows()">Duplicar</button><button onclick="moveRows(-1)" title="Alt + seta para cima">↑ Mover</button><button onclick="moveRows(1)" title="Alt + seta para baixo">↓ Mover</button><button onclick="batch()">Editar em lote</button><button onclick="archiveRows()">${scope==='archive'?'Reativar':'Arquivar'}</button><span class="spacer"></span><button id="undo" onclick="undo()" title="Ctrl Z">↶ Desfazer</button><button id="redo" onclick="redo()" title="Ctrl Y">↷ Refazer</button><button onclick="importPaste()">Colar tabela do Excel</button></div>`}
function tabs(){return `<div class="tabs">${Object.entries({rotina:'Rotina',documentos:'Documentos e valores',prazos:'Datas e tempos',completo:'Todas as colunas'}).map(([k,t])=>`<button class="${view===k?'active':''}" onclick="view='${k}';anchor=null;focusCell=null;rectEnd=null;render()">${t}</button>`).join('')}<span class="spacer"></span><button onclick="document.body.classList.toggle('density-compact')">Compactar linhas</button><button onclick="sortKey='';render()">Ordem manual</button></div>`}
function render(){selected=new Set([...selected].filter(id=>get(id)));visibleRows=filtered();cols=VIEWS[view];if(!get(active))active=visibleRows[0]?.id||state.rows[0]?.id;let intro=`<div class="intro"><div><h2>${C.intro}</h2><p>${C.desc}</p></div><span class="badge gray">${esc(state.workspaceName)} · referência 23/10/2026</span></div>`;let content='';
 if(MODE==='grade'){content=`<main class="workspace">${intro}${portfolioTabs()}<div class="portfolioSummary"><b>${esc(sellerFilter===null?'Todos os vendedores':sellerFilter||'Vendedor não informado')}</b><span>›</span><span>${esc(clientFilter===null?'Todos os clientes':clientFilter||'Cliente não informado')}</span><span class="spacer"></span><small>${visibleRows.length} registros nesta seleção</small><button onclick="clearPortfolio()">Toda a carteira</button></div>${filters()}<section class="panel"><div class="panelhead"><div class="viewSwitch"><button class="${visual==='grid'?'active':''}" onclick="setVisual('grid')">▦ Grade</button><button class="${visual==='cards'?'active':''}" onclick="setVisual('cards')">▤ Cards compactos</button></div><div class="row"><small>${selected.size} linha(s) selecionada(s)</small><button onclick="showSelected()">Abrir ficha</button><button onclick="statsDialog()">Indicadores</button></div></div>${tools()}${visual==='grid'?`<div class="columnTabs">${tabs()}</div>${grid()}${gridFooter()}`:`${compactCards()}<div class="hint">Cards e grade compartilham os dados e as abas de carteira. Clique no card para abrir a ficha. Use a seleção e os comandos acima para trabalhar em lote.</div>`}</section><div class="saveinfo" style="margin-top:10px">${esc(state.source)} · Registros sem vendedor/cliente ficam na aba “Não informado”.</div></main>`}
 if(MODE==='agenda'){content=`<div class="layout"><nav class="rail"><div class="eyebrow">Minha rotina</div>${Object.entries({all:'Toda a carteira',late:'Ações vencidas',today:'Verificar agora',future:'Próximos dias',plan:'Sem agenda'}).map(([k,t])=>`<button class="${channel===k?'active':''}" onclick="setChannel('${k}')">${t}<span>${state.rows.filter(r=>!r.archived&&(k==='all'||queue(r)===k)).length}</span></button>`).join('')}<p>A agenda usa a próxima verificação ou, se vazia, o prazo da ação. Arraste um cartão para reagendar a verificação.<br><br>Use a tabela para alterações em bloco.</p><button onclick="help()">Como trabalhar</button></nav><main class="workspace">${intro}${stats()}${filters()}<div class="tabs"><button class="${visual==='board'?'active':''}" onclick="visual='board';render()">Agenda de trabalho</button><button class="${visual==='grid'?'active':''}" onclick="visual='grid';render()">Tabela de trabalho</button><span class="spacer"></span><button class="primary" onclick="addRow()">＋ Componente</button></div>${visual==='grid'?tabs()+`<section class="panel">${tools()}${grid()}${gridFooter()}</section>`:`${tools()}<div class="actionBanner">${selected.size} selecionado(s) <button onclick="batch()">Atualizar seleção</button><button onclick="selected.clear();render()">Limpar seleção</button><span class="spacer"></span><small>Cartão → ficha completa · arraste → próxima verificação</small></div>${board()}`}</main></div>`}
 if(MODE==='cockpit'){content=`<main class="workspace">${intro}${filters()}<div class="tabs"><button class="${visual==='dossier'?'active':''}" onclick="visual='dossier';render()">Estação de trabalho</button><button class="${visual==='grid'?'active':''}" onclick="visual='grid';render()">Edição em massa</button><span class="spacer"></span><button onclick="navigate(-1)">← Anterior</button><button onclick="navigate(1)">Próximo →</button><button class="primary" onclick="addRow()">＋ Componente</button></div>${visual==='grid'?tabs()+`<section class="panel">${tools()}${grid()}${gridFooter()}</section>`:`<div class="cockpit-layout"><section class="panel"><div class="panelhead"><b>Carteira</b><small>${visibleRows.length} registros</small></div><div class="tools"><button onclick="copyRows(false)">Copiar</button><button onclick="moveRows(-1)">↑</button><button onclick="moveRows(1)">↓</button><button onclick="batch()">Em lote</button><button onclick="archiveRows()">Arquivar</button></div><div class="catalog">${catalog()}</div></section><section class="panel" id="dossier">${get(active)?detail(get(active),false):'<div class="empty">Adicione um componente para começar.</div>'}</section></div>`}</main>`}
 $('#body').innerHTML=content;$('#search').oninput=e=>{q=e.target.value;let p=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(p,p)};bindGrid();bindDrag();saveStatus();paintSelection();}
function gridFooter(){return `<div class="gridFooter"><span id="selectionInfo">${selected.size} linha(s) selecionada(s) · ${sortKey?'Ordenado por '+FM[sortKey][1]:'Ordem manual'}</span><span>Duplo clique/F2: editar · Shift: selecionar intervalo · Ctrl C/V: células · Alt ↑/↓: linhas</span></div><div class="hint">Números à esquerda selecionam linhas inteiras. Ctrl + clique permite seleção múltipla. Arraste o número para mover linhas. Campos calculados são somente leitura. Datas: dd/mm/aaaa.</div>`}
function grid(){return `<div class="tablewrap"><table class="sheet" aria-label="Tabela editável"><colgroup><col style="width:45px">${cols.map(k=>`<col style="width:${FM[k][2]}px">`).join('')}</colgroup><thead><tr><th class="num"><input type="checkbox" aria-label="Selecionar todas as linhas visíveis" ${visibleRows.length&&visibleRows.every(r=>selected.has(r.id))?'checked':''} onchange="selectAll(this.checked)"></th>${cols.map(k=>`<th><button onclick="sortBy('${k}')">${esc(FM[k][1])}${sortKey===k?(sortDir===1?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${visibleRows.map((r,i)=>`<tr data-id="${r.id}" class="${selected.has(r.id)?'rowSelected':''}"><td class="num" draggable="true" data-drag="${r.id}" data-rownum="${i}" title="Selecionar / arrastar linha">${i+1}</td>${cols.map((k,c)=>`<td tabindex="0" class="cell ${FM[k][2]>250?'long':''} ${FM[k][3]==='calc'?'readonly':''}" data-r="${i}" data-c="${c}" data-id="${r.id}" data-key="${k}" title="${esc(display(r,k))}">${esc(display(r,k))}</td>`).join('')}</tr>`).join('')}</tbody></table>${visibleRows.length?'':'<div class="empty">Nenhum registro neste filtro. <button onclick="clearFilters()">Limpar filtros</button></div>'}</div>`}
function agendaDate(r){return r.reviewDate||r.actionDue||''}
function board(){let groups=[['now','Resolver / verificar agora','Verificação ou ação para hoje e antes'],['later','Próximos compromissos','Verificação ou prazo depois da referência'],['none','Organizar a agenda','Sem verificação nem prazo da ação']];return `<div class="board">${groups.map(([key,label,sub])=>{let rs=visibleRows.filter(r=>key==='now'?(agendaDate(r)&&agendaDate(r)<=state.referenceDate):key==='later'?(agendaDate(r)&&agendaDate(r)>state.referenceDate):!agendaDate(r));return `<section class="lane" data-lane="${key}"><div class="laneTitle"><span>${label}</span>${badge(rs.length)}</div><p class="muted" style="font-size:11px;margin:0 4px 12px">${sub}</p>${rs.map(r=>`<article class="task ${selected.has(r.id)?'selected':''}" draggable="true" data-drag="${r.id}"><div class="tasktop"><div><h3>${esc(r.component||'Novo componente')}</h3><small>${esc(r.fleet)} · ${esc(r.site)}</small></div><input type="checkbox" aria-label="Selecionar ${esc(r.component)}" ${selected.has(r.id)?'checked':''} onchange="toggleRow('${r.id}',this.checked)"></div><div style="margin-top:9px">${badge(r.status)} ${overdue(r)?badge('Ação vencida','red'):''}</div><p class="description">${esc(r.nextAction||r.note||r.piecesNote||'Defina o próximo passo deste atendimento.')}</p><label>Próxima ação<input aria-label="Próxima ação ${esc(r.component)}" value="${esc(r.nextAction)}" onchange="editField('${r.id}','nextAction',this.value)"></label><div class="row" style="margin-top:8px;align-items:start"><label style="flex:1">Verificar em<input type="date" value="${r.reviewDate}" onchange="editField('${r.id}','reviewDate',this.value)"></label><label style="flex:1">Prazo da ação<input type="date" value="${r.actionDue}" onchange="editField('${r.id}','actionDue',this.value)"></label></div><div class="taskfoot"><small>${esc(r.os||'Ainda sem OS')}</small><button onclick="showDetail('${r.id}')">Abrir ficha ↗</button></div></article>`).join('')||'<div class="empty" style="padding:25px 5px">Arraste componentes para cá.</div>'}</section>`}).join('')}</div>`}
function catalog(){return visibleRows.map(r=>{let n=Math.max(0,statuses.indexOf(r.status));return `<article class="component-item ${active===r.id?'active':''}" data-drag="${r.id}" draggable="true" onclick="active='${r.id}';render()"><input type="checkbox" aria-label="Selecionar ${esc(r.component)}" ${selected.has(r.id)?'checked':''} onclick="event.stopPropagation()" onchange="toggleRow('${r.id}',this.checked)">${badge(r.status)}<h3>${esc(r.component||'Novo componente')}</h3><p>${esc(r.fleet)} · ${esc(r.site)}</p><small>${esc(r.os||'Recebido sem OS')}</small><p>${esc(r.nextAction||r.note||'Próxima ação a definir')}</p><div class="progress">${[0,1,2,3,4].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div></article>`}).join('')||'<div class="empty">Nenhum registro.</div>'}
function field(r,k,wide=false){let f=FM[k],t=f?.[3],v=r[k]??'',opts=k==='status'?statuses:k==='situation'?situations:k==='decision'?['Aprovado','Reprovado','Não se aplica']:k==='invoice'?['Sim','Não','A confirmar']:null;return `<label class="${wide?'wide':''}">${esc(f?.[1]||k)}${opts?`<select data-field="${k}" onchange="editField('${r.id}','${k}',this.value)"><option value="">Não informado</option>${[...new Set([...opts,...(v?[v]:[])])].map(x=>`<option ${v===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:['note','piecesNote','nextAction','internal'].includes(k)?`<textarea data-field="${k}" onchange="editField('${r.id}','${k}',this.value)">${esc(v)}</textarea>`:`<input data-field="${k}" type="${t==='date'?'date':k==='invoiceMonth'?'month':'text'}" value="${esc(t==='money'&&v!==''?String(v).replace('.',','):v)}" onchange="editField('${r.id}','${k}',this.value)">`}</label>`}
function detail(r,inModal){let tab=inModal?modalTab:detail.tab||'rotina';let tabsHTML=`<div class="tabs">${Object.entries({rotina:'Acompanhamento',dados:'Cadastro e valores',datas:'Datas e tempos',sap:'Referência SAP',history:'Histórico'}).map(([k,t])=>`<button class="${tab===k?'active':''}" onclick="${inModal?`modalTab='${k}';showDetail('${r.id}',true)`:`detail.tab='${k}';render()`}">${t}</button>`).join('')}</div>`;let inner='';
 if(tab==='rotina')inner=`<div class="formgrid">${['status','situation','forecast','piecesNote','note','nextAction','owner','actionDue','reviewDate','invoice','invoiceMonth','confirmed'].map(k=>field(r,k,['piecesNote','note','nextAction'].includes(k))).join('')}</div><div class="actionBanner"><button class="primary" onclick="confirmRow('${r.id}')">Conferido em ${date(state.referenceDate)}</button><button onclick="completeAction('${r.id}')">Concluir ação atual</button><button onclick="reviewTomorrow('${r.id}')">Verificar amanhã</button></div><div class="section"><h3>Anotação interna</h3><div class="formgrid">${field(r,'internal',true)}</div></div>`;
 if(tab==='dados')inner=`<div class="formgrid">${['component','fleet','seller','client','site','os','type','requisition','nf','order','parts','services'].map(k=>field(r,k)).join('')}</div><div class="note">Total calculado: <strong data-live-total="${r.id}">${display(r,'total')||'Sem valor informado'}</strong>. Os valores desta ficha são os do controle do planejador. A referência SAP fica na aba própria para comparação.</div><div class="section"><h3>OSs deste atendimento</h3><div class="row">${expandOS(r.os).map(x=>`<button onclick="copyText(${esc(JSON.stringify(x))})">${esc(x)} ⧉</button>`).join('')||'<small>Ainda sem OS vinculada.</small>'}</div><p class="muted" style="font-size:12px;margin-top:12px">Você pode manter a notação 800000001/02 ou separar os números completos por ponto e vírgula.</p></div>`;
 if(tab==='datas')inner=`<div class="timeline">${[['arrival','Chegada'],['notification','Notificação'],['opened','Abertura'],['quoted','Orçamento entregue'],['approved','Decisão'],['shipped','Envio']].map(([k,l])=>`<div class="milestone"><small>${l}</small><b>${date(r[k])||'—'}</b></div>`).join('')}</div><div class="formgrid">${['arrival','notification','opened','budgetForecast','quoted','decision','approved','forecast','shipped'].map(k=>field(r,k)).join('')}</div><div class="metrics">${['ltNotification','ltBudget','ltApproval','age'].map(k=>`<div class="metric"><small>${FM[k][1]}</small><strong>${calc(r,k)===''?'—':calc(r,k)+' dias'}</strong></div>`).join('')}</div><div class="note">Previsões não encerram fases. “Dias desde notificação” continua até a data de referência, como na planilha. Datas fora de sequência ficam visíveis; valores negativos pedem conferência. A decisão deve indicar se houve aprovação ou reprovação.</div>`;
 if(tab==='sap')inner=`<div class="note">Retrato do JSON enviado em 23/10/2026, somente para consulta. Não há consulta online ao SAP/PartsVis nem atualização automática desses valores. Use os números para consultar os sistemas e registre o resultado em Acompanhamento.</div>${r.sap?.length?r.sap.map(s=>`<section class="section"><div class="row"><h3>OS ${esc(s.os)}</h3><button onclick="copyText(${esc(JSON.stringify(s.os))})">Copiar OS</button>${badge(s.stage)}${badge(s.origin,'gray')}</div><table class="sourceTable"><tr><th>Cliente / modelo / série</th><td>${esc(s.client)} · ${esc(s.model)} · ${esc(s.serial)}</td></tr><tr><th>Serviço</th><td>${esc(s.service)}</td></tr><tr><th>Peças no JSON</th><td>${fmtMoney.format(s.parts)}</td></tr>${Object.entries(s.dates||{}).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${date(v)||'—'}</td></tr>`).join('')}</table></section>`).join(''):'<div class="empty">Sem correspondência no JSON de referência. O registro pode continuar sendo acompanhado.</div>'}`;
 if(tab==='history')inner=`<div class="note">Edições ficam neste histórico. Conferir a OS é uma ação explícita; editar uma observação não renova a confirmação.</div><div class="history">${(r.history||[]).map(e=>`<div class="event"><small>${new Date(e.at).toLocaleString('pt-BR')}</small>${esc(e.text)}</div>`).join('')||'<div class="empty">Sem alterações nesta prévia.</div>'}</div>`;
 return `<div class="detail"><div class="detailTitle"><div><div class="eyebrow">${esc(r.site||'Site a informar')} / ${esc(r.type||'Tipo a informar')}</div><h2>${esc(r.component||'Novo componente')}</h2><p>${esc(r.fleet)} · ${esc(r.os||'Ainda sem OS')}</p><p style="font-size:12px">${esc(r.seller||'Vendedor não informado')} · ${esc(r.client||'Cliente não informado')}</p></div>${badge(r.status)}</div><div class="row" style="margin-bottom:16px"><button onclick="copyText(get('${r.id}').os)">Copiar OSs</button><button onclick="copyText(get('${r.id}').order)">Copiar pedido</button><button onclick="copySummary('${r.id}')">Copiar resumo</button><button onclick="showRelated('${r.id}')">Relacionadas</button>${!inModal?'<span class="spacer"></span><button id="undo" onclick="undo()">↶</button><button id="redo" onclick="redo()">↷</button>':''}</div>${tabsHTML}${inner}<div class="hint" style="margin-top:18px">Campos são gravados ao sair deles. Ctrl S baixa/salva o backup de toda a carteira. Rascunho local não sincroniza computadores.</div></div>`}
function refreshDetail(){if(modalRow&&get(modalRow))showDetail(modalRow,true)}
function dialog(title,body,footer='',small=false){$('#modal').innerHTML=`<div class="dialogback"><section class="dialog ${small?'small':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialogheader"><h2>${title}</h2><button aria-label="Fechar" onclick="closeModal()">✕</button></div><div class="dialogbody">${body}</div>${footer?`<div class="dialogfooter">${footer}</div>`:''}</section></div>`}
function closeModal(){document.activeElement?.blur();modalRow=null;$('#modal').innerHTML='';render()}
function showDetail(id,keep=false){if(!get(id))return;if(!keep)modalTab='rotina';modalRow=id;dialog('Ficha do componente',detail(get(id),true));saveStatus()}
function showSelected(){showDetail([...selected][0]||visibleRows[focusCell?.r||0]?.id||active)}
function showRelated(id){let r=get(id),roots=expandOS(r.os).map(x=>x.slice(0,-2));let rs=state.rows.filter(x=>x.id!==id&&expandOS(x.os).some(y=>roots.includes(y.slice(0,-2))));modalRow=null;dialog('OSs relacionadas',`<p>Registros do controle com a mesma raiz de OS. O vínculo é uma sugestão para consulta; valores e campos continuam independentes.</p>${rs.map(x=>`<div class="actionBanner"><b>${esc(x.component)}</b> ${esc(x.os)} <span class="spacer"></span><button onclick="showDetail('${x.id}')">Abrir</button></div>`).join('')||'<div class="empty">Não há outro registro com a mesma raiz de OS.</div>'}`)}
function expandOS(s){return String(s||'').split(/[;,\n]+/).flatMap(chunk=>{let ps=chunk.trim().split('/').map(x=>x.trim()).filter(Boolean);return ps.length?[ps[0],...ps.slice(1).map(x=>x.length<ps[0].length?ps[0].slice(0,-x.length)+x:x)]:[]})}
function parseValue(k,s){s=String(s??'').trim();if(FM[k]?.[3]==='date'){if(!s)return '';if(/^\d{2}\/\d{2}\/\d{4}$/.test(s))s=s.slice(6)+'-'+s.slice(3,5)+'-'+s.slice(0,2);if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||isNaN(Date.parse(s))||new Date(s+'T12:00Z').toISOString().slice(0,10)!==s)throw Error('Data inválida em '+FM[k][1]+'. Use dd/mm/aaaa.');return s}if(FM[k]?.[3]==='money'){if(!s)return '';s=s.replace(/R\$|\s/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');if(!/^-?\d+(\.\d+)?$/.test(s)||!Number.isFinite(Number(s)))throw Error('Valor inválido em '+FM[k][1]);return Number(s)}if(k==='invoiceMonth'&&s&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(s))throw Error('Mês deve estar no formato aaaa-mm.');return s}
function editField(id,k,value){try{let v=parseValue(k,value),r=get(id);if(r[k]===v)return;checkpoint('Editar '+FM[k][1]);let old=r[k];r[k]=v;if(k==='seller'||k==='client')refreshPortfolio();history(r,FM[k][1]+': '+String(old||'vazio')+' → '+String(v||'vazio'));changed('');saveStatus();document.querySelectorAll('[data-live-total]').forEach(el=>{if(el.dataset.liveTotal===id)el.textContent=display(r,'total')||'Sem valor informado'});}catch(e){toast(e.message)}}
function addRow(){let r=emptyRow();r.seller=sellerFilter||'';r.client=clientFilter||'';mutate('Adicionar componente',()=>{let ix=state.rows.findIndex(x=>x.id===( [...selected][0]||active));state.rows.splice(ix+1,0,r);active=r.id;selected=new Set([r.id]);q='';site='';status='';channel='all';scope='active'});if(visual==='grid'){let ix=visibleRows.findIndex(x=>x.id===r.id);focusAt(ix,0);beginEdit(cellAt(ix,0))}else if(MODE==='agenda'||(MODE==='grade'&&visual==='cards'))showDetail(r.id)}
function emptyRow(){return {...Object.fromEntries(F.filter(f=>f[3]!=='calc').map(f=>[f[0],''])),seller:sellerFilter||'',client:clientFilter||'',id:uid(),history:[],archived:false,sap:[],sourceRow:null}}
function setChannel(c){channel=c;render()}
function clearFilters(){q='';site='';status='';channel='all';scope='active';sortKey='';sellerFilter=clientFilter=null;tabSearch='';resetSelection();savePortfolio();render()}
function changeReference(v){if(!v)return;mutate('Mudar data de referência',()=>state.referenceDate=v)}
function sortBy(k){sortDir=sortKey===k?-sortDir:1;sortKey=k;anchor=focusCell=rectEnd=null;render()}
function toggleRow(id,on){on?selected.add(id):selected.delete(id);active=id;render()}
function selectAll(on){visibleRows.forEach(r=>on?selected.add(r.id):selected.delete(r.id));render()}
function targetIds(){return selected.size?[...selected]:focusCell&&visibleRows[focusCell.r]?[visibleRows[focusCell.r].id]:active?[active]:[]}
function archiveRows(){let ids=targetIds();if(!ids.length)return;let ar=scope!=='archive';mutate(ar?'Arquivar registros':'Reativar registros',()=>ids.forEach(id=>get(id).archived=ar),ids);toast(ar?'Arquivados. Use o filtro Arquivados para reativar ou Ctrl Z.':'Registros reativados.');}
function duplicateRows(){let ids=targetIds();if(!ids.length)return;mutate('Duplicar linhas',()=>{let created=[];ids.forEach(id=>{let old=get(id),r=structuredClone(old);r.id=uid();r.history=[];history(r,'Cópia do registro '+(old.os||old.component));state.rows.splice(state.rows.indexOf(old)+1,0,r);created.push(r.id)});selected=new Set(created);active=created[0]});toast('Linhas duplicadas. Revise OSs e documentos para evitar duplicidade.')}
function canMove(){if(sortKey){toast('Escolha “Ordem manual” antes de movimentar linhas.');return false}return true}
function moveRows(dir){if(!canMove())return;let ids=targetIds(),set=new Set(ids);mutate('Mover linhas',()=>{if(dir<0){for(let i=1;i<state.rows.length;i++)if(set.has(state.rows[i].id)&&!set.has(state.rows[i-1].id))[state.rows[i-1],state.rows[i]]=[state.rows[i],state.rows[i-1]]}else for(let i=state.rows.length-2;i>=0;i--)if(set.has(state.rows[i].id)&&!set.has(state.rows[i+1].id))[state.rows[i],state.rows[i+1]]=[state.rows[i+1],state.rows[i]]});}
function moveTo(ids,before){if(!canMove()||ids.includes(before))return;mutate('Mover linhas por arraste',()=>{let set=new Set(ids),moving=state.rows.filter(r=>set.has(r.id));state.rows=state.rows.filter(r=>!set.has(r.id));let ix=state.rows.findIndex(r=>r.id===before);state.rows.splice(ix<0?state.rows.length:ix,0,...moving)});}
function bindDrag(){document.querySelectorAll('[data-drag]').forEach(el=>{el.ondragstart=e=>{if(e.target.matches('input,textarea,select')){e.preventDefault();return}let id=el.dataset.drag;dragRows=selected.has(id)?[...selected]:[id];e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragRows.join(','))};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();e.stopPropagation();if(dragRows)moveTo(dragRows,el.dataset.drag);dragRows=null}});document.querySelectorAll('[data-lane]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(!dragRows)return;let ids=dragRows;if(el.dataset.lane==='none'&&ids.some(id=>get(id).actionDue)){toast('Este registro possui prazo de ação. Limpe o prazo na ficha se quiser deixá-lo sem agenda.');dragRows=null;return}let v=el.dataset.lane==='now'?state.referenceDate:el.dataset.lane==='later'?plusDay(state.referenceDate,1):'';mutate('Reagendar verificação',()=>ids.forEach(id=>get(id).reviewDate=v),ids);dragRows=null;toast('Próxima verificação atualizada. O prazo da ação foi preservado.')};el.querySelectorAll('[data-drag]').forEach(x=>x.ondrop=null)})}
function plusDay(d,n){let x=new Date(d+'T12:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)}
function reviewTomorrow(id){mutate('Verificar novamente amanhã',()=>get(id).reviewDate=plusDay(state.referenceDate,1),[id]);refreshDetail()}
function confirmRow(id){mutate('Situação conferida em '+date(state.referenceDate),()=>get(id).confirmed=state.referenceDate,[id]);refreshDetail()}
function completeAction(id){let r=get(id);if(!r.nextAction)return toast('Defina uma ação antes de concluir.');mutate('Ação concluída: '+r.nextAction,()=>{r.nextAction='';r.actionDue=''},[id]);refreshDetail();toast('Ação registrada no histórico. Defina o próximo passo quando necessário.')}
function navigate(n){let i=visibleRows.findIndex(r=>r.id===active);active=visibleRows[Math.max(0,Math.min(visibleRows.length-1,i+n))]?.id||active;render()}
function batch(){let ids=targetIds();if(!ids.length)return toast('Selecione ao menos uma linha.');pickPending=ids;modalRow=null;dialog('Editar '+ids.length+' registro(s)',`<p>Escolha um campo. O valor será aplicado a todos os registros selecionados. Campo vazio limpa o conteúdo; você poderá desfazer.</p><div class="formgrid"><label class="wide">Campo<select id="batchKey">${F.filter(f=>f[3]!=='calc').map(([k,l])=>`<option value="${k}" ${k==='situation'?'selected':''}>${l}</option>`).join('')}</select></label><label class="wide">Novo valor<input id="batchValue" placeholder="Texto, valor ou data dd/mm/aaaa"></label></div>`,`<button onclick="closeModal()">Cancelar</button><button class="primary" onclick="applyBatch()">Aplicar à seleção</button>`,true)}
function applyBatch(){let k=$('#batchKey').value;try{let v=parseValue(k,$('#batchValue').value),ids=pickPending;mutate('Atualização em lote: '+FM[k][1]+' = '+v,()=>ids.forEach(id=>get(id)[k]=v),ids);closeModal();toast(ids.length+' registros atualizados.')}catch(e){toast(e.message)}}
function copySummary(id){let r=get(id);copyText([r.component+' · '+r.fleet+' · '+r.site,'OS: '+(r.os||'Não informada'),'Situação: '+(r.situation||r.status),r.piecesNote,r.note,'Próxima ação: '+(r.nextAction||'Não definida'),'Previsão de conclusão: '+(date(r.forecast)||'Não informada'),'Última confirmação: '+(date(r.confirmed)||'Não informada')].filter(Boolean).join('\n'))}
function tsvCell(v){v=String(v??'');return /[\t\n\r"]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function toTSV(rows,keys,header=false){return (header?[keys.map(k=>FM[k][1])]:[]).concat(rows.map(r=>keys.map(k=>display(r,k)))).map(row=>row.map(tsvCell).join('\t')).join('\r\n')}
function parseTSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'&&(quoted||cell==='')){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(!quoted&&(c==='\t'||c==='\n'||c==='\r')){row.push(cell);cell='';if(c!=='\t'){rows.push(row);row=[];if(c==='\r'&&text[i+1]==='\n')i++}}else cell+=c}if(cell!==''||row.length) {row.push(cell);rows.push(row)}return rows}
async function copyText(text){if(!text)return toast('Sem conteúdo para copiar.');try{await navigator.clipboard.writeText(text);toast('Copiado.')}catch{let t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();let ok=document.execCommand('copy');t.remove();if(ok)toast('Copiado.');else {modalRow=null;dialog('Copiar conteúdo',`<p>Selecione o texto abaixo e use Ctrl C.</p><textarea id="copyFallback" style="width:100%;min-height:180px">${esc(text)}</textarea>`,'',true);$('#copyFallback').select()}}}
let rowClipboard=null;
function copyRows(cut){let ids=targetIds();if(!ids.length)return;rowClipboard=ids.map(id=>structuredClone(get(id)));cutRows=cut?ids:null;copyText(toTSV(rowClipboard,F.filter(f=>f[3]!=='calc').map(f=>f[0])));toast(cut?'Linhas recortadas. Escolha o destino e use “Colar linhas”.':'Linhas copiadas. Use “Colar linhas” ou cole no Excel.')}
function pasteRowsAfter(){if(!rowClipboard)return toast('Use “Copiar linhas” ou “Recortar linhas” primeiro. Para Excel, use “Colar tabela do Excel”.');let dest=targetIds()[0]||active;if(cutRows?.includes(dest))return toast('Selecione uma linha fora do conjunto recortado.');mutate(cutRows?'Recortar e mover linhas':'Colar cópia de linhas',()=>{let entries;if(cutRows){let set=new Set(cutRows);entries=state.rows.filter(r=>set.has(r.id));state.rows=state.rows.filter(r=>!set.has(r.id))}else entries=rowClipboard.map(r=>({...structuredClone(r),id:uid(),history:[{at:new Date().toISOString(),text:'Linha colada de uma cópia'}]}));let ix=state.rows.findIndex(r=>r.id===dest);state.rows.splice(ix+1,0,...entries);selected=new Set(entries.map(r=>r.id));active=entries[0].id;cutRows=null});}
function importPaste(){modalRow=null;dialog('Colar tabela do Excel',`<p>Cole um bloco do Excel. Com cabeçalhos, os nomes da planilha original e deste painel são reconhecidos. Sem cabeçalho, será usada a ordem de colunas da visão <b>${esc(view)}</b>.</p><textarea id="pasteBox" style="width:100%;height:220px" placeholder="Ctrl V aqui"></textarea><div class="row" style="margin-top:10px"><label><input type="checkbox" id="pasteHeaders" checked> A primeira linha contém cabeçalhos</label></div><p class="muted">Importação adiciona linhas, sem substituir as existentes. Valores calculados serão refeitos. Revise possíveis OSs duplicadas.</p>`,`<button onclick="closeModal()">Cancelar</button><button class="primary" onclick="applyImportPaste()">Adicionar linhas</button>`)}
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const aliases={'componente':'component','frota':'fleet','requisicao':'requisition','nf':'nf','pedido':'order','ossotreq':'os','tipo':'type','status':'status','pecas':'parts','servicosdiversos':'services','total':'total','observacaopecas':'piecesNote','observacaoadcional':'note','observacaoadicional':'note','datachegada':'arrival','datanotificacao':'notification','dataaberturaos':'opened','entregaorcamento':'quoted','dataaprovacaoreprovacao':'approved','dataenvio':'shipped','leadtimenotificacao':'ltNotification','slaorcamento':'ltBudget','leadtimeaprovacao':'ltApproval','prazoemaberto':'age','site':'site','responsavelcomercial':'seller','nomevendedor':'seller','nomecliente':'client',...Object.fromEntries(F.map(([k,l])=>[norm(l),k]))};
function applyImportPaste(){try{let matrix=parseTSV($('#pasteBox').value);if(!matrix.length)throw Error('Cole uma tabela primeiro.');let keys=$('#pasteHeaders').checked?matrix.shift().map(x=>aliases[norm(x)]):cols;if(!keys.some(Boolean))throw Error('Nenhum cabeçalho reconhecido.');let unknown=keys.filter(k=>!k).length;if(unknown)throw Error(unknown+' cabeçalho(s) não reconhecido(s). Ajuste os títulos antes de importar.');let added=matrix.filter(x=>x.some(v=>v.trim())).map((arr,i)=>{let r=emptyRow();arr.forEach((v,c)=>{let k=keys[c];if(c>=keys.length)throw Error('Linha '+(i+1)+' tem colunas além dos cabeçalhos.');if(k&&FM[k][3]!=='calc')r[k]=parseValue(k,v)});history(r,'Importado por colagem do Excel');return r});mutate('Importar '+added.length+' linhas do Excel',()=>{state.rows.push(...added);q='';site='';status='';channel='all';scope='active';selected=new Set(added.map(r=>r.id))});closeModal();toast(added.length+' linhas adicionadas.')}catch(e){toast(e.message)}}
function portfolioRows(){return state.rows.filter(r=>scope==='all'||(scope==='archive'?r.archived:!r.archived))}
function portfolioCounts(rs,key){const m=new Map();rs.forEach(r=>{let name=r[key]||'';m.set(name,(m.get(name)||0)+1)});return [...m].sort((a,b)=>a[0]&&b[0]?a[0].localeCompare(b[0],'pt-BR'):a[0]?-1:b[0]?1:0)}
function portfolioTabs(){let rs=portfolioRows(),sellers=portfolioCounts(rs,'seller'),clients=portfolioCounts(rs.filter(r=>sellerFilter===null||(r.seller||'')===sellerFilter),'client');return `<div id="portfolioNav" class="portfolioNav"><div class="portfolioLine"><span class="portfolioLabel">VENDEDOR</span><div class="portfolioStrip" role="group" aria-label="Carteiras de vendedores"><button class="portfolioTab ${sellerFilter===null?'active':''}" aria-pressed="${sellerFilter===null}" onclick="chooseSeller(null)">Todos <small>${rs.length}</small></button>${sellers.map(([name,n])=>`<button class="portfolioTab ${sellerFilter===name?'active':''}" data-value="${esc(name)}" aria-pressed="${sellerFilter===name}" onclick="chooseSeller(this.dataset.value)" title="${esc(name||'Vendedor não informado')}">${esc(name||'Não informado')} <small>${n}</small></button>`).join('')}</div></div><div class="portfolioLine clientLine"><span class="portfolioLabel">CLIENTE</span><div class="portfolioStrip" role="group" aria-label="Clientes da carteira"><button class="portfolioTab ${clientFilter===null?'active':''}" aria-pressed="${clientFilter===null}" onclick="chooseClient(null)">Todos <small>${clients.reduce((n,x)=>n+x[1],0)}</small></button>${clients.map(([name,n])=>`<button class="portfolioTab ${clientFilter===name?'active':''}" data-value="${esc(name)}" aria-pressed="${clientFilter===name}" onclick="chooseClient(this.dataset.value)" title="${esc(name||'Cliente não informado')}">${esc(name||'Não informado')} <small>${n}</small></button>`).join('')}</div></div></div>`}
function refreshPortfolio(){const nav=$('#portfolioNav');if(nav&&MODE==='grade')nav.outerHTML=portfolioTabs()}
function resetSelection(){selected.clear();anchor=focusCell=rectEnd=null}
function savePortfolio(){try{localStorage.setItem(KEY+'-view',JSON.stringify({seller:sellerFilter,client:clientFilter,visual}))}catch{}}
function chooseSeller(name){document.activeElement?.blur();sellerFilter=name;clientFilter=null;resetSelection();savePortfolio();render()}
function chooseClient(name){document.activeElement?.blur();clientFilter=name;resetSelection();savePortfolio();render()}
function clearPortfolio(){sellerFilter=clientFilter=null;resetSelection();savePortfolio();render()}
function setVisual(name){document.activeElement?.blur();visual=name;anchor=focusCell=rectEnd=null;savePortfolio();render()}
function compactCards(){return `<div class="compactCards">${visibleRows.map(r=>`<article class="compactCard ${selected.has(r.id)?'selected':''}" data-drag="${r.id}" draggable="true" tabindex="0" onclick="if(event.ctrlKey||event.metaKey){toggleRow('${r.id}',!selected.has('${r.id}'))}else{showDetail('${r.id}')}" onkeydown="if(event.key==='Enter'){showDetail('${r.id}')}" aria-label="Abrir ${esc(r.component)}"><div class="compactTop"><div><strong title="${esc(r.component)}">${esc(r.component||'Novo componente')}</strong><span>${esc(r.fleet||'Frota não informada')} · ${esc(r.os||'Ainda sem OS')}</span></div><input type="checkbox" aria-label="Selecionar ${esc(r.component)}" ${selected.has(r.id)?'checked':''} onclick="event.stopPropagation()" onchange="toggleRow('${r.id}',this.checked)"></div><div class="compactClient" title="${esc(r.client)} · ${esc(r.seller)}">${esc(r.client||'Cliente não informado')} <small>· ${esc(r.seller||'Vendedor não informado')}</small></div><div class="compactStatus">${badge(r.situation||r.status)}${overdue(r)?badge('Ação vencida','red'):''}</div><p title="${esc(r.nextAction||r.note||r.piecesNote)}">${esc(r.nextAction||r.note||r.piecesNote||'Próxima ação a definir.')}</p><div class="compactFoot"><span>${r.reviewDate?'Verificar '+date(r.reviewDate):r.actionDue?'Ação até '+date(r.actionDue):'Sem verificação agendada'}</span><button onclick="event.stopPropagation();showDetail('${r.id}')">Abrir ↗</button></div></article>`).join('')||'<div class="empty">Nenhum registro nesta seleção. <button onclick="clearFilters()">Limpar filtros</button></div>'}</div>`}
function statsDialog(){modalRow=null;let rs=filtered();dialog('Indicadores da seleção',`<p>${rs.length} registros · ${esc(sellerFilter===null?'Todos os vendedores':sellerFilter||'Sem vendedor')} · ${esc(clientFilter===null?'Todos os clientes':clientFilter||'Sem cliente')}</p><div class="stats"><div class="stat"><small>EM EXIBIÇÃO</small><strong>${rs.length}</strong></div><div class="stat"><small>AÇÕES VENCIDAS</small><strong>${rs.filter(overdue).length}</strong></div><div class="stat"><small>VERIFICAR AGORA</small><strong>${rs.filter(r=>queue(r)==='today').length}</strong></div><div class="stat"><small>SEM AGENDA</small><strong>${rs.filter(r=>queue(r)==='plan').length}</strong></div></div><p class="muted">Os números respeitam as abas, filtros e busca atuais.</p>`)}
function examples(){modalRow=null;dialog('Escolher uma amostra para avaliação',`<p>As amostras contêm exclusivamente dados fictícios. ${dirty?'<b>Há alterações sem backup.</b> Salve o controle atual antes de trocar, se quiser preservá-las.':'Você pode salvar o controle atual e retomá-lo depois.'}</p><div class="exampleOptions"><button onclick="loadExample('aga')"><b>Carteira fictícia completa</b><span>48 atendimentos fictícios da planilha Componentes em Processo. Vendedor preenchido onde houve correspondência no JSON.</span></button><button onclick="loadExample('multi')"><b>Carteira multivendedor · Planejador Exemplo</b><span>18 atendimentos fictícios do JSON · 3 vendedores · 11 clientes. Dados gerados artificialmente para avaliar a navegação.</span></button></div>`,`<button onclick="closeModal()">Voltar</button><button class="primary" onclick="saveFile()">Salvar controle atual</button>`,true)}
function loadExample(name){mutate('Carregar amostra '+name,()=>{state.rows=structuredClone(name==='multi'?MULTI:SEED);state.workspaceName=name==='multi'?'Amostra multicarteira · Planejador Exemplo':'Carteira fictícia · 48 atendimentos';state.source=name==='multi'?'18 atendimentos fictícios de 23/10/2026 · amostra para navegação por vendedor/cliente':'Base sintética para avaliação · 23/10/2026';state.referenceDate='2026-10-23';active=state.rows[0]?.id;resetSelection();sellerFilter=clientFilter=null;q=site=status='';channel='all';scope='active';sortKey='';fileHandle=null});savePortfolio();$('#refDate').value=state.referenceDate;closeModal();toast('Amostra aberta. Ctrl Z permite voltar à carteira anterior nesta sessão.')}
function cellAt(r,c){return document.querySelector(`td.cell[data-r="${r}"][data-c="${c}"]`)}
function focusAt(r,c,extend=false){r=Math.max(0,Math.min(visibleRows.length-1,r));c=Math.max(0,Math.min(cols.length-1,c));if(r<0)return;focusCell={r,c};if(!extend||!anchor)anchor={r,c};rectEnd={r,c};let el=cellAt(r,c);el?.focus();el?.scrollIntoView({block:'nearest',inline:'nearest'});paintSelection()}
function bounds(){if(!anchor)return null;let e=rectEnd||anchor;return {r0:Math.min(anchor.r,e.r),r1:Math.max(anchor.r,e.r),c0:Math.min(anchor.c,e.c),c1:Math.max(anchor.c,e.c)}}
function paintSelection(){let b=bounds();document.querySelectorAll('tr[data-id]').forEach(el=>el.classList.toggle('rowSelected',selected.has(el.dataset.id))); $$('td.cell').forEach(el=>{let r=+el.dataset.r,c=+el.dataset.c;el.classList.toggle('selected',!!b&&r>=b.r0&&r<=b.r1&&c>=b.c0&&c<=b.c1);el.classList.toggle('focused',focusCell?.r===r&&focusCell?.c===c)});if($('#selectionInfo'))$('#selectionInfo').textContent=selected.size+' linha(s) selecionada(s)'+(b?' · bloco '+(b.r1-b.r0+1)+' × '+(b.c1-b.c0+1):'')+(sortKey?' · ordem classificada':' · ordem manual')}
function bindGrid(){document.querySelectorAll('[data-rownum]').forEach(el=>{el.onclick=e=>{let i=+el.dataset.rownum,id=visibleRows[i].id;if(e.shiftKey&&selected.size){let a=visibleRows.findIndex(r=>selected.has(r.id));for(let x=Math.min(a,i);x<=Math.max(a,i);x++)selected.add(visibleRows[x].id)}else if(e.ctrlKey||e.metaKey){selected.has(id)?selected.delete(id):selected.add(id)}else selected=new Set([id]);active=id;anchor=focusCell=rectEnd=null;render()};el.ondblclick=()=>showDetail(visibleRows[+el.dataset.rownum].id)});$$('td.cell').forEach(el=>{el.onclick=e=>{if(el.isContentEditable)return;if(!e.shiftKey)selected.clear();active=el.dataset.id;focusAt(+el.dataset.r,+el.dataset.c,e.shiftKey)};el.ondblclick=()=>beginEdit(el);el.onkeydown=cellKey});}
function beginEdit(el,initial){if(!el||FM[el.dataset.key][3]==='calc')return toast('Campo calculado. Edite as datas ou valores de origem.');el.dataset.old=el.textContent;el.contentEditable='true';el.textContent=initial??String(display(get(el.dataset.id),el.dataset.key));el.focus();let range=document.createRange();range.selectNodeContents(el);let sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);if(initial!==undefined)sel.collapseToEnd();el.onblur=()=>commitEdit(el)}
function commitEdit(el){if(!el.isContentEditable)return true;let k=el.dataset.key,id=el.dataset.id,txt=el.textContent;el.contentEditable='false';el.onblur=null;try{let v=parseValue(k,txt),r=get(id);if(r[k]!==v){checkpoint('Editar '+FM[k][1]);let old=r[k];r[k]=v;if(k==='seller'||k==='client')refreshPortfolio();history(r,FM[k][1]+': '+String(old||'vazio')+' → '+String(v||'vazio'));changed('')}el.textContent=display(r,k);document.querySelectorAll('td.cell[data-id="'+id+'"]').forEach(c=>{if(FM[c.dataset.key]?.[3]==='calc')c.textContent=display(r,c.dataset.key)});return true}catch(e){el.textContent=el.dataset.old;toast(e.message);return false}}
function cellKey(e){let el=e.currentTarget,r=+el.dataset.r,c=+el.dataset.c;if(el.isContentEditable){if(e.key==='Escape'){e.preventDefault();el.contentEditable='false';el.onblur=null;el.textContent=el.dataset.old;return}if(e.key==='Enter'&&!e.altKey||e.key==='Tab'){e.preventDefault();commitEdit(el);render();focusAt(e.key==='Enter'?r+(e.shiftKey?-1:1):r,e.key==='Tab'?c+(e.shiftKey?-1:1):c)}return}if(e.key==='F2'||e.key==='Enter'){e.preventDefault();beginEdit(el);return}if(e.key==='Tab'){e.preventDefault();focusAt(r,c+(e.shiftKey?-1:1));return}let delta={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]}[e.key];if(delta&&!e.altKey){e.preventDefault();focusAt(r+delta[0],c+delta[1],e.shiftKey);return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();clearCells();return}if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();beginEdit(el,e.key)}}
function clearCells(){let b=bounds();if(!b)return;mutate('Limpar células',()=>{for(let r=b.r0;r<=b.r1;r++)for(let c=b.c0;c<=b.c1;c++)if(FM[cols[c]][3]!=='calc')visibleRows[r][cols[c]]=''});}
function pasteMatrix(matrix){if(!focusCell)return false;let start=focusCell,b=bounds(),fill=matrix.length===1&&matrix[0].length===1&&b&&(b.r1>b.r0||b.c1>b.c0),updates=[],newRows=[];try{let n=fill?b.r1-b.r0+1:matrix.length;for(let ri=0;ri<n;ri++){let vals=fill?Array(b.c1-b.c0+1).fill(matrix[0][0]):matrix[ri];let rIndex=(fill?b.r0:start.r)+ri,target=visibleRows[rIndex];if(!target){target=emptyRow();newRows.push(target)}for(let ci=0;ci<vals.length;ci++){let col=(fill?b.c0:start.c)+ci,k=cols[col];if(!k)throw Error('O bloco ultrapassa a última coluna. Use a visão Todas as colunas.');if(FM[k][3]==='calc')continue;updates.push([target,k,parseValue(k,vals[ci])])}}checkpoint('Colar bloco de células');updates.forEach(([r,k,v])=>{r[k]=v});state.rows.push(...newRows);[...new Set(updates.map(x=>x[0].id))].forEach(id=>history(get(id),'Colagem de bloco de células'));changed('');render();focusAt(start.r,start.c);toast(updates.length+' células coladas'+(newRows.length?' · '+newRows.length+' linhas adicionadas':''));return true}catch(e){toast(e.message);return false}}
document.addEventListener('copy',e=>{if(e.target.matches('input,textarea')||e.target.isContentEditable)return;let b=bounds();if(selected.size){rowClipboard=state.rows.filter(r=>selected.has(r.id)).map(r=>structuredClone(r));cutRows=null;e.clipboardData.setData('text/plain',toTSV(rowClipboard,cols));e.preventDefault()}else if(b){let rs=visibleRows.slice(b.r0,b.r1+1),ks=cols.slice(b.c0,b.c1+1);e.clipboardData.setData('text/plain',toTSV(rs,ks));e.preventDefault()}});
document.addEventListener('paste',e=>{if(e.target.matches('input,textarea')||e.target.isContentEditable)return;let text=e.clipboardData.getData('text/plain');if(selected.size&&rowClipboard&&[toTSV(rowClipboard,cols),toTSV(rowClipboard,F.filter(f=>f[3]!=='calc').map(f=>f[0]))].includes(text)){e.preventDefault();pasteRowsAfter();return}if(e.target.closest('.sheet')&&focusCell){e.preventDefault();pasteMatrix(parseTSV(text))}});
document.addEventListener('cut',e=>{if(e.target.matches('input,textarea')||e.target.isContentEditable)return;if(selected.size){rowClipboard=state.rows.filter(r=>selected.has(r.id)).map(r=>structuredClone(r));cutRows=[...selected];e.clipboardData.setData('text/plain',toTSV(rowClipboard,cols));e.preventDefault();toast('Linhas recortadas. Use Ctrl V ou “Colar linhas” no destino.')}else if(bounds()){let b=bounds();e.clipboardData.setData('text/plain',toTSV(visibleRows.slice(b.r0,b.r1+1),cols.slice(b.c0,b.c1+1)));e.preventDefault();clearCells()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();document.activeElement?.blur();saveFile();return}let editing=e.target.matches('input,textarea,select')||e.target.isContentEditable;if(editing)return;if(e.key==='Escape'){if($('#modal').innerHTML)closeModal();else {selected.clear();anchor=focusCell=rectEnd=null;paintSelection()}return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo()}if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();moveRows(e.key==='ArrowUp'?-1:1)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();let b=bounds();if(b&&b.r1>b.r0){let vals=cols.slice(b.c0,b.c1+1).map(k=>display(visibleRows[b.r0],k));checkpoint('Preencher abaixo');try{let ups=[];for(let r=b.r0+1;r<=b.r1;r++)vals.forEach((v,i)=>{let k=cols[b.c0+i];if(FM[k][3]!=='calc')ups.push([visibleRows[r],k,parseValue(k,v)])});ups.forEach(([r,k,v])=>r[k]=v);changed('');render()}catch(err){undoStack.pop();toast(err.message)}}}if((e.ctrlKey||e.metaKey)&&e.key===' '){e.preventDefault();selectAll(true)}});
function download(name,data,type){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function downloadTable(){download('Carteira_'+MODE+'_'+state.referenceDate+'.tsv','\ufeff'+toTSV(filtered(),F.map(x=>x[0]),true),'text/tab-separated-values;charset=utf-8');toast('Tabela filtrada exportada em TSV para abrir no Excel.')}
async function saveFile(){document.activeElement?.blur();let exported=new Date().toISOString(),payload=JSON.stringify({...state,exportedAt:exported},null,2),name='Controle_Planejador_'+MODE+'_'+localToday()+'.json';try{if(window.showSaveFilePicker){if(!fileHandle)fileHandle=await showSaveFilePicker({suggestedName:name,types:[{description:'Controle do planejador',accept:{'application/json':['.json']}}]});let writable=await fileHandle.createWritable();await writable.write(payload);await writable.close();toast('Backup salvo no arquivo escolhido.')}else {download(name,payload,'application/json');toast('Backup gerado para download. Guarde o JSON junto do HTML.')}state.exportedAt=exported;dirty=false;persist()}catch(e){if(e.name==='AbortError')return;download(name,payload,'application/json');toast('Não foi possível gravar direto. Backup gerado para download.');state.exportedAt=exported;dirty=false;persist()}}
function openFile(){document.activeElement?.blur();$('#fileInput').value='';$('#fileInput').click()}
function validateState(s){if(s?.schema!=='planejador-experimentos'||s.version!==1||!Array.isArray(s.rows))throw Error('Escolha um backup Controle_Planejador gerado por uma destas três versões. O JSON gerencial atual tem outro formato e não será alterado.');let ids=new Set();s.rows.forEach((r,i)=>{if(typeof r.id!=='string'||!/^[\w-]+$/.test(r.id)||ids.has(r.id))throw Error('Identificação inválida ou repetida na linha '+(i+1));ids.add(r.id);let original=SEED.find(x=>x.id===r.id);for(const k of ['seller','client'])if(r[k]===undefined)r[k]=original?.[k]||'';F.filter(f=>f[3]!=='calc').forEach(([k])=>{if(r[k]!==undefined)r[k]=parseValue(k,r[k]);else r[k]=''});if(!Array.isArray(r.history)||!Array.isArray(r.sap))throw Error('Estrutura de histórico/referência inválida.');r.archived=!!r.archived});parseValue('reviewDate',s.referenceDate);return s}
async function loadFile(e){let f=e.target.files[0];if(!f)return;try{let s=validateState(JSON.parse(await f.text()));pickPending=s;modalRow=null;dialog('Abrir controle',`<p><b>${esc(f.name)}</b></p><p>${s.rows.length} registros · referência ${date(s.referenceDate)}.</p><p>${dirty?'Há alterações sem backup no controle aberto. Salve antes de substituir, se quiser preservá-las.':'O controle do arquivo substituirá a carteira exibida.'}</p>`,`<button onclick="closeModal()">Cancelar</button>${dirty?'<button onclick="saveFile()">Salvar controle atual</button>':''}<button class="primary" onclick="applyOpen()">Abrir este arquivo</button>`,true)}catch(err){toast(err.message)}}
function applyOpen(){checkpoint('Abrir outro controle');state=pickPending;dirty=false;fileHandle=null;active=state.rows[0]?.id;selected.clear();q=site=status='';channel='all';scope='active';sellerFilter=clientFilter=null;tabSearch='';anchor=focusCell=rectEnd=null;persist();closeModal();$('#refDate').value=state.referenceDate;render();toast('Controle aberto. Os backups são compatíveis entre as três propostas.')}
function help(){modalRow=null;dialog('Como usar '+C.title,`<div class="note"><b>Prévia funcional para avaliação.</b> Os 48 atendimentos fictícios vieram da planilha enviada. As referências SAP e alguns campos operacionais vieram do JSON de 23/10/2026. Cada HTML tem rascunho próprio; use o backup JSON para transportar os mesmos dados entre as três versões.</div><div class="note"><b>Carteiras como abas.</b> Os nomes vêm das colunas Vendedor e Cliente. Escolha um vendedor e depois um cliente; a grade e os cards mostram a mesma seleção. As contagens das abas consideram a carteira ativa/arquivada, sem reduzir a lista pela busca textual. “Toda a carteira” limpa apenas essas duas seleções. “Limpar filtros” limpa tudo. Use Exemplos para testar os 48 atendimentos fictícios Cliente Demonstração ou 18 atendimentos fictícios da carteira multivendedor.</div><div class="helpgrid"><article><h3>01 · Abrir e retomar</h3><p>Abra este HTML no Edge ou Chrome. Ao voltar, o rascunho deste navegador é retomado. “Abrir controle” carrega um backup JSON destas versões. Limpeza de dados do navegador ou mudança de computador pode remover o rascunho.</p></article><article><h3>02 · Editar como uma tabela</h3><p>Duplo clique ou F2 edita a célula. Enter confirma e desce; Tab vai para a direita. Clique e Shift + clique selecionam um bloco. Setas com Shift também ampliam a seleção.</p><p><kbd>Ctrl C</kbd> <kbd>Ctrl V</kbd> copiam e colam blocos com Excel, inclusive textos com quebras de linha. Uma célula colada sobre um bloco preenche todo o bloco.</p></article><article><h3>03 · Linhas e movimentação</h3><p>Clique no número da linha; Ctrl + clique seleciona várias e Shift seleciona intervalo. Arraste o número ou use Alt + ↑/↓. Ctrl C/X/V nas linhas selecionadas ou os botões Copiar/Recortar/Colar linhas mantêm todos os campos, mesmo os ocultos. Ao colar no Excel, os atalhos levam as colunas da visão atual.</p><p>Movimentação usa a ordem completa da carteira. Com filtros, registros ocultos também ocupam posições. Para arrastar, use a ordem manual.</p></article><article><h3>04 · Menos preenchimento repetido</h3><p>“Editar em lote” aplica um campo à seleção. Ctrl D preenche abaixo com a primeira linha do bloco. Arquivar tira o registro da carteira ativa; reative no filtro Arquivados. Ctrl Z/Y desfaz/refaz até 50 operações da sessão.</p></article><article><h3>05 · Salvar e fechar</h3><p>Ctrl S ou “Salvar backup” salva um JSON. Quando o navegador permitir, escolha um arquivo e os próximos salvamentos atualizam essa cópia. Caso contrário, será baixado um novo arquivo.</p><p>O aviso superior indica alterações sem backup. Ao fechar, o navegador pode pedir confirmação. O rascunho e o backup são independentes.</p></article><article><h3>06 · SAP, PartsVis e compartilhamento</h3><p>Use “Copiar OSs” e “Copiar pedido” para consultar os sistemas. A referência SAP é uma fotografia, sem acesso online. Registre o resultado e a próxima verificação.</p><p>Estes JSONs ainda não são respostas importáveis no painel gerencial atual. A integração será feita após escolhermos o modelo. Não há sincronização simultânea entre usuários.</p></article></div><div class="section"><h3>Datas e rotina</h3><p>A referência começa em 23/10/2026 para comparar os mesmos exemplos. Altere no topo para o dia desejado. Editar dados não confirma a OS automaticamente. “Conferido” registra a confirmação explicitamente; concluir uma ação guarda o texto no histórico e libera o campo para a próxima.</p></div><button onclick="resetDemo()">Recomeçar avaliação com os dados originais</button>`)}
function resetDemo(){dialog('Recomeçar avaliação',`<p>Os dados originais desta prévia voltarão à tela. ${dirty?'Há alterações sem backup.':'Seu backup em arquivo não será alterado.'}</p>`,`<button onclick="closeModal()">Cancelar</button><button onclick="saveFile()">Salvar antes</button><button class="primary" onclick="doReset()">Recomeçar</button>`,true)}
function doReset(){loadExample('aga')}
window.addEventListener('beforeunload',e=>{document.activeElement?.blur();persist();if(dirty){e.preventDefault();e.returnValue=''}});
try{let saved=localStorage.getItem(KEY);if(saved){let s=validateState(JSON.parse(saved));dirty=!!s._dirty;delete s._dirty;state=s;restored=true}}catch{storageOK=false}
if(MODE==='grade'){let savedNav;try{savedNav=JSON.parse(localStorage.getItem(KEY+'-view')||'null')}catch{}if(savedNav){sellerFilter=typeof savedNav.seller==='string'?savedNav.seller:null;clientFilter=typeof savedNav.client==='string'?savedNav.client:null;visual=savedNav.visual==='cards'?'cards':'grid'}}
shell();
